import{battles,commanders,eraInfo}from"./data.js";import{TabNav}from"./components/TabNav.js";import{BattleTimeline}from"./components/BattleTimeline.js";import{BattleCard,BattleDetail}from"./components/BattleCard.js";import{BattleMap}from"./components/BattleMap.js";import{CommandersGallery}from"./components/CommandersGallery.js";const TABS=[{id:"timeline",label:"Timeline"},{id:"ancient",label:"Ancient"},{id:"medieval",label:"Medieval"},{id:"colonial",label:"Colonial"},{id:"modern",label:"Modern"},{id:"maps",label:"Maps"},{id:"commanders",label:"Commanders"}];let activeTab="timeline";function renderTabNav(){document.getElementById("battles-tab-nav-root").innerHTML=TabNav(TABS,activeTab)}function renderContent(){const e=document.getElementById("battles-tab-content-root");e.style.opacity="0",setTimeout(()=>{e.innerHTML=getTabContent(activeTab),attachListeners(),e.style.opacity="1"},150)}function getTabContent(e){switch(e){case"timeline":return BattleTimeline(battles,eraInfo);case"ancient":return renderEraTab("ancient");case"medieval":return renderEraTab("medieval");case"colonial":return renderEraTab("colonial");case"modern":return renderEraTab("modern");case"maps":return BattleMap(battles,eraInfo);case"commanders":return CommandersGallery(commanders);default:return""}}function renderEraTab(e){const t=battles.filter(t=>t.era===e);if(0===t.length)return'<div class="no-results">No battles found for this era.</div>';const a=t.map((e,t)=>BattleCard(e,eraInfo,t)).join("");return`\n        <div class="era-header" style="border-left: 4px solid ${eraInfo[e].color}">\n            <h3>${eraInfo[e].label}</h3>\n            <p>${eraInfo[e].description}</p>\n        </div>\n        <div class="battles-grid">\n            ${a}\n        </div>\n    `}function attachListeners(){document.querySelectorAll(".battle-expand-btn").forEach(e=>{e.addEventListener("click",()=>{const t=parseInt(e.dataset.index),a=e.closest(".battle-card"),n="timeline"===activeTab?a.dataset.era:activeTab,r=battles.filter(e=>e.era===n)[t];if(!r)return;if("true"===e.getAttribute("aria-expanded")){const t=a.querySelector(".battle-detail-panel");t&&t.remove(),e.setAttribute("aria-expanded","false"),e.querySelector("span").textContent="Full Battle Details",e.classList.remove("expanded")}else{const t=document.createElement("div");t.className="battle-detail-panel",t.innerHTML=BattleDetail(r),a.appendChild(t),e.setAttribute("aria-expanded","true"),e.querySelector("span").textContent="Collapse",e.classList.add("expanded")}})}),document.querySelectorAll(".map-marker").forEach(e=>{e.addEventListener("click",()=>{const t=parseInt(e.dataset.index),a=battles[t];if(!a)return;document.querySelectorAll(".map-marker").forEach(e=>e.classList.remove("active")),e.classList.add("active");let n=document.getElementById("map-popup");n||(n=document.createElement("div"),n.id="map-popup",n.className="map-popup",document.querySelector(".battle-map-container").appendChild(n));const r=eraInfo[a.era]||{color:"#888"};n.innerHTML=`\n                <div class="popup-header" style="border-left: 4px solid ${r.color}">\n                    <button class="popup-close" id="popup-close-btn">&times;</button>\n                    <span class="popup-era" style="color: ${r.color}">${r.label}</span>\n                    <h4>${a.name}</h4>\n                    <p class="popup-date">${a.date}</p>\n                </div>\n                <p class="popup-location">${a.location}</p>\n                <p class="popup-summary">${a.summary.substring(0,200)}...</p>\n                <div class="popup-outcome">\n                    <strong>Outcome:</strong> ${a.outcome}\n                </div>\n            `,n.classList.add("visible"),document.getElementById("popup-close-btn").addEventListener("click",()=>{n.classList.remove("visible"),e.classList.remove("active")})})})}document.addEventListener("DOMContentLoaded",()=>{document.getElementById("battles-app").innerHTML='\n        <div id="battles-tab-nav-root"></div>\n        <div id="battles-tab-content-root"></div>\n    ',renderTabNav(),renderContent(),document.getElementById("battles-tab-nav-root").addEventListener("click",e=>{const t=e.target.closest(".battles-tab-btn");t&&(activeTab=t.dataset.tab,renderTabNav(),renderContent())})});